function updateSaveState(){const button=$('flowSave');if(!button)return;const hasFilters=Object.keys(urlFlowFilters()).length>0;button.disabled=!hasFilters;button.title=hasFilters?'Save filters, columns and time range':'Add a filter before saving a view'}
async function loadFlows(reset=false){
  const out=$('flowOut');if(!out)return;
  if(reset){lastCursor='';flowCursorStack=[]}
  const query=++flowQuerySequence,limit=$('flowLimit')?.value||'100',p=qs({...urlFlowFilters(),limit});if(lastCursor)p.set('cursor',lastCursor);
  out.innerHTML='<div class="loading-state" role="status">Searching flow storage…</div>';
  try{const x=await api('/api/v1/flows/page?'+p);if(query!==flowQuerySequence||!out.isConnected)return;flowRows=x.rows||[];flowNextCursor=x.next_cursor||'';drawFlows()}
  catch(e){if(e.name!=='AbortError'&&out.isConnected&&query===flowQuerySequence)out.innerHTML=errorPanel(e.message)}
}
function flowCell(r,key){
  if(key==='src_ip'||key==='dst_ip')return `<button class="linklike ip-link mono" data-ip="${esc(r[key])}">${esc(r[key])}</button><button class="port-link" data-filter-port="${key==='src_ip'?'src_port':'dst_port'}" data-value="${Number(r[key==='src_ip'?'src_port':'dst_port'])||0}" title="Filter by port">:${Number(r[key==='src_ip'?'src_port':'dst_port'])||0}</button>`;
  if(key==='bytes')return bytes(r.bytes);if(key==='packets')return fmt(r.packets);if(key==='receive_time')return esc(dateTime(r.receive_time));if(key==='country')return esc(flowPlace(r));if(key==='asn')return r.dst_as||r.src_as?`<button class="linklike drill mono" data-dim="asn" data-key="${Number(r.dst_as||r.src_as)}">AS${Number(r.dst_as||r.src_as)}</button>`:'—';
  if(key==='exporter')return `<button class="linklike drill mono" data-dim="exporter" data-key="${esc(r.exporter)}">${esc(r.exporter)}</button>`;
  if(key==='ip_protocol')return `<button class="linklike drill" data-dim="protocol" data-key="${esc(r.ip_protocol)}">${esc(({1:'ICMP',6:'TCP',17:'UDP',47:'GRE',58:'ICMPv6'})[r.ip_protocol]||r.ip_protocol)}</button>`;
  return esc(r[key]??'—');
}
function drawFlows(){
  const cols=selectedColumns(),out=$('flowOut');if(!out)return;
  out.innerHTML=`<div class="table-wrap flow-table"><table><thead><tr><th scope="col" class="row-index">#</th>${cols.map(k=>`<th scope="col" data-col="${k}" class="${['bytes','packets','sampling_rate'].includes(k)?'numeric':''}"><span>${esc(flowColumns.find(([x])=>x===k)[1])}${k==='receive_time'?' ↓':''}</span><span class="resize-handle" role="separator" aria-label="Resize ${esc(k)} column" aria-orientation="vertical" tabindex="0"></span></th>`).join('')}<th scope="col"><span class="sr-only">Row detail</span></th></tr></thead><tbody>${flowRows.length?flowRows.map((r,i)=>`<tr><td class="row-index">${String(i+1).padStart(2,'0')}</td>${cols.map(k=>`<td class="${['bytes','packets','sampling_rate'].includes(k)?'numeric':''}">${flowCell(r,k)}</td>`).join('')}<td><button class="row-detail ghost" data-row="${i}" aria-label="Open flow ${i+1} details">↗</button></td></tr>`).join(''):`<tr><td colspan="${cols.length+2}">${empty('No flows match these conditions.',false)}<button class="ghost small" data-clear-filters>Clear filters</button></td></tr>`}</tbody></table></div><div class="pagination"><span><b>${fmt(flowRows.length)}</b> records on page ${flowCursorStack.length+1}<span class="muted"> · selected period ${esc(rangeLabel())}</span></span><div class="actions"><button id="flowPrev" class="ghost small" ${flowCursorStack.length?'':'disabled'}>← Previous</button><button id="flowNext" class="ghost small" ${flowNextCursor?'':'disabled'}>Next →</button></div></div>`;
  $('flowNext').onclick=()=>{flowCursorStack.push(lastCursor);lastCursor=flowNextCursor;loadFlows(false)};$('flowPrev').onclick=()=>{lastCursor=flowCursorStack.pop()||'';loadFlows(false)};
  $$('.resize-handle').forEach(handle=>{const th=handle.parentElement;const resize=w=>{th.style.width=th.style.minWidth=Math.max(70,Math.min(550,w))+'px'};handle.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();resize(th.offsetWidth+(e.key==='ArrowRight'?16:-16))}};handle.onpointerdown=e=>{e.preventDefault();const x=e.clientX,w=th.offsetWidth;handle.setPointerCapture(e.pointerId);handle.onpointermove=ev=>resize(w+ev.clientX-x);handle.onpointerup=()=>{handle.onpointermove=null}}});
}
function columnEditor(){const cols=selectedColumns();openModal(`<div class="modal-heading"><span class="eyebrow">FLOW EXPLORER</span><h3>Visible columns</h3></div><div class="column-options">${flowColumns.map(([k,n])=>`<label><input type="checkbox" value="${k}" ${cols.includes(k)?'checked':''}>${n}</label>`).join('')}</div><button id="columnsApply">Apply columns</button>`);$('columnsApply').onclick=()=>{const values=$$('.column-options input:checked').map(e=>e.value);if(!values.length)return toast('Select at least one column.','bad');const u=new URL(location.href);u.searchParams.set('columns',values.join(','));setURL(u,true);closeModal();drawFlows()}}
function rowDetail(index){const r=flowRows[index];if(!r)return;openModal(`<div class="modal-heading"><span class="eyebrow">FLOW RECORD</span><h3>${esc(r.src_ip)} → ${esc(r.dst_ip)}</h3><p class="muted">${dateTime(r.receive_time)} · ${esc(r.flow_protocol)}</p></div><div class="record-fields">${Object.entries(r).filter(([,v])=>v!==null&&v!=='').map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><code>${esc(typeof v==='object'?JSON.stringify(v):v)}</code><button class="ghost small" data-copy="${esc(typeof v==='object'?JSON.stringify(v):v)}" aria-label="Copy ${esc(k)}">Copy</button></div>`).join('')}</div>`)}
async function loadSavedViews(){const el=$('savedViews');if(!el)return;try{const views=(await api('/api/v1/searches')).filter(v=>v.visualization!=='intelligence');if(!el.isConnected)return;el.innerHTML=`<label class="sr-only" for="savedViewSelect">Saved Views</label><select id="savedViewSelect"><option value="">Saved Views (${views.length})</option>${views.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select>`;$('savedViewSelect').onchange=e=>{const view=views.find(v=>v.id===e.target.value);if(!view)return;let u=PortalState.setFilters(location.href,view.query||{});u.searchParams.set('columns',(view.columns||defaultColumns).join(','));const savedTime=view.time_config||'24h';if(savedTime.startsWith('{')){try{const t=JSON.parse(savedTime);rangeKey='custom';rangeCustom={from:new Date(t.from),to:new Date(t.to)}}catch{rangeKey='24h';rangeCustom=null}}else{rangeKey=ranges[savedTime]||savedTime==='live'?savedTime:'24h';rangeCustom=null}setURL(timeURL(u));render()}}catch(e){if(e.name!=='AbortError')el.textContent='Saved views unavailable'}}
function saveView(){if(!Object.keys(urlFlowFilters()).length)return toast('Add at least one filter before saving a view.','bad');openModal('<div class="modal-heading"><span class="eyebrow">SAVED VIEW</span><h3>Keep this analysis</h3></div><form id="saveViewForm"><div class="field"><label>Name<input id="viewName" required maxlength="100" autocomplete="off"></label></div><p class="muted">Saves filters, visible columns, newest-first order and time range.</p><button>Save View</button><div id="saveViewError" class="error"></div></form>');$('saveViewForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/v1/searches',{method:'POST',body:JSON.stringify({name:$('viewName').value.trim(),query:urlFlowFilters(),columns:selectedColumns(),sort:'receive_time desc',visualization:'table',time_config:rangeCustom?JSON.stringify(rangeCustom):rangeKey})});closeModal();toast('View saved');loadSavedViews()}catch(err){$('saveViewError').textContent=err.message}}}
