function matrixHTML(rows,metric='bytes'){
  if(!rows.length)return empty('No source-to-destination pairs in this period.');
  const ranked=[...rows].sort((a,b)=>b[metric]-a[metric]);
  const rankNetworks=key=>[...new Set(rows.map(r=>r[key]))].sort((a,b)=>rows.filter(r=>r[key]===b).reduce((n,r)=>n+r[metric],0)-rows.filter(r=>r[key]===a).reduce((n,r)=>n+r[metric],0)).slice(0,12);
  const sources=rankNetworks('source'),destinations=rankNetworks('destination'),max=Math.max(1,...rows.map(r=>r[metric])),format=metric==='bytes'?bytes:fmt;
  const byPair=new Map(rows.map(r=>[r.source+'|'+r.destination,r]));
  return `<div class="matrix-caption"><span>↓ SOURCE NETWORK / DESTINATION NETWORK →</span><div class="matrix-legend">Lower <i></i><i></i><i></i><i></i> Higher · ${format(max)}</div></div><div class="matrix-scroll"><table class="network-matrix"><thead><tr><th scope="col">Source / destination</th>${destinations.map(n=>`<th scope="col"><span title="${esc(n)}">${esc(n)}</span></th>`).join('')}</tr></thead><tbody>${sources.map(src=>`<tr><th scope="row">${esc(src)}</th>${destinations.map(dst=>{const r=byPair.get(src+'|'+dst);return `<td>${r?`<button class="matrix-cell" style="--weight:${Math.max(7,Math.round(85*r[metric]/max))}%" data-source="${esc(src)}" data-destination="${esc(dst)}" title="${esc(src)} → ${esc(dst)} · ${format(r[metric])} · ${fmt(r.flows)} flows" aria-label="${esc(src)} to ${esc(dst)}, ${format(r[metric])}. Open matching flows."><b>${format(r[metric])}</b></button>`:'<span class="matrix-missing" title="Pair not in the returned top results">—</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="matrix-footer"><span>${sources.length} source / ${destinations.length} destination networks shown · — means outside returned top pairs</span><span>Select a cell to open Flow Explorer ↗</span></div><div class="section-ruler"><span>STRONGEST RELATIONSHIPS</span><span>Exact values / selected metric</span></div><div class="matrix-pairs">${ranked.slice(0,5).map((r,i)=>`<button data-source="${esc(r.source)}" data-destination="${esc(r.destination)}"><span class="muted">0${i+1}</span><code>${esc(r.source)}</code><span>→</span><code>${esc(r.destination)}</code><b>${format(r[metric])}</b></button>`).join('')}</div>`;
}
