async function exportersPage(){
  title('Exporters','Telemetry sources and decoding quality');
  const h=await api('/api/v1/exporters/health');
  const healthy=h.filter(x=>x.state==='healthy').length,offline=h.filter(x=>x.state==='down').length,degraded=h.length-healthy-offline;
  $('content').innerHTML=`<div class="section-ruler"><span>COLLECTION INVENTORY</span><span>Current state · rates since first observation</span></div><div class="kpis">${kpi('Exporters',fmt(h.length))}${kpi('Healthy',fmt(healthy))}${kpi('Degraded / stale',fmt(degraded))}${kpi('Offline',fmt(offline))}${kpi('Decode errors',fmt(h.reduce((n,x)=>n+x.decode_errors,0)))}${kpi('Sequence gaps',fmt(h.reduce((n,x)=>n+x.sequence_gaps,0)))}</div><div id="exporterTrendOut"></div><div class="results-toolbar"><div class="actions"><label class="sr-only" for="exporterSearch">Filter exporters by IP or protocol</label><input id="exporterSearch" placeholder="Filter by IP, protocol or listener…"><label class="sr-only" for="exporterState">Exporter status</label><select id="exporterState"><option value="">All states</option><option value="healthy">Healthy</option><option value="degraded">Degraded / stale</option><option value="down">Offline</option></select></div><button class="ghost small" data-route="system">Ingestion pipeline →</button></div><section class="card exporter-table"><div id="exporterTable"></div></section>`;
  let sort='address',descending=false;
  const columns=[['address','Exporter'],['protocol','Protocol'],['state','Status'],['last_seen','Last seen'],['flow_rate','Flows / s'],['packet_rate','Packets / s'],['flows','Flows'],['decode_errors','Decode errors'],['sequence_gaps','Sequence gaps'],['template_status','Template']];
  const draw=()=>{const search=$('exporterSearch').value.toLowerCase(),state=$('exporterState').value;const rows=h.filter(x=>(x.address+' '+x.protocol+' '+x.listener).toLowerCase().includes(search)&&(!state||(state==='degraded'?x.state!=='healthy'&&x.state!=='down':x.state===state))).sort((a,b)=>{const av=a[sort],bv=b[sort];return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv)))*(descending?-1:1)});
    $('exporterTable').innerHTML=table(columns.map(([,label])=>label),rows.map(x=>[`<button class="linklike drill mono" data-dim="exporter" data-key="${esc(x.address)}">${esc(x.address)}</button>`,x.protocol,`<span class="pill ${x.state==='healthy'?'good':x.state==='down'?'bad':'warn'}">${x.state==='healthy'?'✓ Healthy':x.state==='down'?'− Offline':esc(x.state)}</span>`,age(x.last_seen),fmt(x.flow_rate),fmt(x.packet_rate),fmt(x.flows),fmt(x.decode_errors),fmt(x.sequence_gaps),x.template_status]),true);
    $$('#exporterTable th').forEach((th,i)=>{th.setAttribute('aria-sort',columns[i][0]===sort?(descending?'descending':'ascending'):'none');th.innerHTML=`<button class="sort-button" data-sort="${columns[i][0]}">${columns[i][1]} ${columns[i][0]===sort?(descending?'↓':'↑'):'↕'}</button>`;th.querySelector('button').onclick=()=>{const key=columns[i][0];descending=key===sort?!descending:false;sort=key;draw()}});
  };$('exporterSearch').oninput=draw;$('exporterState').onchange=draw;draw();
  const trend=await exporterTrendPanel();if($('exporterTrendOut')){$('exporterTrendOut').innerHTML=trend;bindTrafficVisualCharts()}
}
function pipelineView(h,d,exporters){
  const listeners=h.listeners||[],s=h.storage||{},sum=k=>listeners.reduce((n,l)=>n+Number(l[k]||0),0),queue=sum('queue_depth'),capacity=sum('queue_capacity');
  const stages=[['Receive',fmt(sum('packets'))+' packets',fmt(sum('drops'))+' drops',sum('drops')?'warn':''],['Decode',fmt(d.analytics?.total_flows)+' flows',fmt(exporters.reduce((n,e)=>n+e.decode_errors,0))+' decode errors',exporters.some(e=>e.decode_errors)?'warn':''],['Normalize',fmt(h.analytics_capacity?.source_keys)+' sources',fmt(h.analytics_capacity?.state_drops)+' state-capacity drops',h.analytics_capacity?.state_drops?'warn':''],['Queue',`${fmt(queue)} / ${fmt(capacity)}`,'listener queue depth',capacity&&queue/capacity>.8?'warn':''],['Storage',fmt(s.written)+' written',`${fmt(s.write_errors)} write errors · ${fmt(s.dropped)} drops`,s.healthy?'good':'bad']];
  return `<div class="pipeline">${stages.map(([name,value,detail,tone],i)=>`<div class="pipeline-stage ${tone}"><span class="stage-index">0${i+1}</span><h3>${name}</h3><b>${esc(value)}</b><small>${esc(detail)}</small>${i<4?'<span class="stage-arrow" aria-hidden="true">→</span>':''}</div>`).join('')}</div>`;
}
function capacityView(c,s={}){const used=Number(c.bytes_on_disk)||0,total=Number(c.total_bytes)||0;return `<div class="capacity-value"><b>${bytes(used)}</b><span>flow storage / ${esc(c.backend||s.backend||'unknown')}</span></div>${total?`<meter class="disk-meter" min="0" max="${total}" value="${Math.min(total,used)}" aria-label="Flow storage as a proportion of filesystem capacity"></meter>`:''}<dl class="metric-list"><div><dt>Retention</dt><dd>${fmt(c.retention_days)} days</dd></div><div><dt>Daily growth</dt><dd>${c.daily_growth_bytes==null?'Unavailable':bytes(c.daily_growth_bytes)}</dd></div><div><dt>Estimated remaining</dt><dd>${c.estimated_remaining_days?fmt(c.estimated_remaining_days)+' days':'Insufficient growth history'}</dd></div><div><dt>Free on filesystem</dt><dd>${c.free_bytes==null?'Unavailable':bytes(c.free_bytes)}</dd></div><div><dt>WAL / spool</dt><dd>${s.backend==='clickhouse'?bytes(s.spool_bytes||0)+' / '+fmt(s.spool_files||0)+' files':'Not used by local storage'}</dd></div></dl>`}
async function systemPage(){
  title('System','Ingestion, storage and operational health');
  const version=renderVersion;
  const [h,c,d,exporters]=await Promise.all([cachedAPI('/api/v1/health'),cachedAPI('/api/v1/storage/capacity'),cachedAPI('/api/v1/dashboard'),api('/api/v1/exporters/health')]);
  if(version!==renderVersion)return;
  const listeners=h.listeners||[],s=h.storage||{};
  $('content').innerHTML=`<div class="section-ruler"><span>INGESTION PIPELINE</span><span>Current snapshot / counters since service start</span></div>${pipelineView(h,d,exporters)}<div class="system-layout">${panel('Listeners',table(['Listener','Protocol','Status','Packets','Drops','Queue'],listeners.map(l=>[l.name,l.protocol,l.running?'Running':'Stopped',fmt(l.packets),fmt(l.drops),`${fmt(l.queue_depth)} / ${fmt(l.queue_capacity)}`])),'Bounded receive queues')}${panel('Storage & capacity',capacityView(c,s),s.healthy?'✓ Database healthy':'Database degraded')}</div><div class="system-layout">${panel('Runtime',`<dl class="metric-list"><div><dt>Heap memory</dt><dd>${bytes(h.runtime?.heap_bytes)}</dd></div><div><dt>Goroutines</dt><dd>${fmt(h.runtime?.goroutines)}</dd></div><div><dt>Storage queue</dt><dd>${fmt(s.queue_depth)} / ${fmt(s.queue_capacity)}</dd></div><div><dt>GC cycles</dt><dd>${fmt(h.runtime?.gc_cycles)}</dd></div></dl>`)}${panel('Collector administration',`<div class="system-links"><button data-route="exporters">Exporter health <span>→</span></button><button data-route="policy">Source admission <span>→</span></button>${me?.role==='administrator'?'<button data-route="admin">Configuration & users <span>→</span><button id="tokenManager">API tokens <span>→</span><button id="auditLog">Audit events <span>→</span>':''}</div>`)}</div>`;
  if(h.notifications)$('content').insertAdjacentHTML('beforeend',panel('Seasonal anomaly evaluation',table(['Evaluations','Withheld','Query errors','Schedule'],[[fmt(h.notifications.seasonal_evaluations),fmt(h.notifications.seasonal_withheld),fmt(h.notifications.seasonal_errors),'Hourly, for enabled seasonal rules']]),'Withheld means comparable unsampled history or current records were unavailable.','<button data-route="notifications" class="ghost small">Open rules and alert lifecycle →</button>'));
  $('tokenManager')?.addEventListener('click',tokenManager);$('auditLog')?.addEventListener('click',auditLog);
}
