  $('content').innerHTML=rangeToolbar()+`<div class="report-layout"><section class="report-config"><div class="section-ruler"><span>REPORT CONFIGURATION</span><span>01 / CONFIGURE</span></div><h3>Network usage report</h3><p class="muted">Traffic summary, leading contributors and timeline for the selected period.</p><div class="field"><label>Report name<input id="repName" value="Network Usage Report" maxlength="120"></label></div><div class="field"><label>Output format<select id="repFmt"><option value="pdf">PDF · shareable document</option><option value="xlsx">XLSX · spreadsheet analysis</option><option value="csv">CSV · tabular data</option><option value="json">JSON · structured data</option></select></label></div>${lensBar(urlFlowFilters(),true)}<div class="report-period"><span class="label">REPORT PERIOD</span><b>${esc(rangeLabel())}</b><small class="muted">One selected period · filtered network usage</small></div><button id="repDownload">Generate & download ↗</button><div id="reportStatus" role="status"></div></section><section class="report-history"><div class="section-ruler"><span>SCHEDULED REPORTS</span><span>${jobs.length} configured</span></div>${canManage?'<div class="results-toolbar"><button id="addReportJob" class="small">+ Add scheduled report</button><span class="muted">Generated files are retained in the collector data directory. Email delivery is optional per schedule; configured webhooks remain active.</span></div>':''}${jobs.length?table(['Name','Format','Schedule','Delivery','Status','Last run','Last result','Actions'],jobs.map(j=>[j.name,j.format.toUpperCase(),reportScheduleLabel(j),delivery(j),j.enabled?'Enabled':'Paused',j.last_run?age(j.last_run):'Not run',j.last_error?`<span class="error">${esc(j.last_error)}</span>`:(j.last_run?'Succeeded':'—'),actions(j)]),true):'<div class="empty"><b>No scheduled reports configured</b><span>Add one to generate network usage reports automatically.</span></div>'}<div class="report-contents"><span class="eyebrow">INCLUDED IN YOUR REPORT</span><ol><li><b>Traffic summary</b><span>Flows, packets and bytes</span></li><li><b>Network contributors</b><span>Sources, destinations, protocols and applications</span></li><li><b>Query context</b><span>Time window and active filters</span></li></ol></div></section></div>`;
  $('repDownload').onclick=downloadReport;$('addReportJob')?.addEventListener('click',()=>reportJobModal());
  const byID=new Map(jobs.map(j=>[j.id,j]));
