async function globalSearch(value){value=value.trim();if(!validIP(value))return toast('Enter a complete IPv4 or IPv6 address.','bad');hideSearch();return ipDetail(value)}
function hideSearch(){searchController?.abort();$('searchResults').classList.add('hidden');$('globalSearch').setAttribute('aria-expanded','false')}
function scheduleSearch(value){clearTimeout(searchTimer);searchController?.abort();if(!validIP(value.trim()))return hideSearch();searchTimer=setTimeout(async()=>{const ip=value.trim();searchController=new AbortController();const box=$('searchResults');box.classList.remove('hidden');$('globalSearch').setAttribute('aria-expanded','true');box.innerHTML='<div class="search-loading" role="status">Looking up endpoint…</div>';try{const [x,g]=await Promise.all([api('/api/v1/ip/'+encodeURIComponent(ip)+'?'+qs({limit:'1'}),{signal:searchController.signal}),api('/api/v1/geoip?ips='+encodeURIComponent(ip),{signal:searchController.signal}).catch(()=>({}))]);if($('globalSearch').value.trim()!==ip)return;const geo=g[ip]||{};box.innerHTML=`<button class="search-result" data-ip="${esc(ip)}"><span class="mono">${esc(ip)} <small>Open profile ↗</small></span><span>${bytes(x.bytes_in+x.bytes_out)} · ${fmt(x.flows)} flows</span><small>${esc(geo.asn?'AS'+geo.asn:'ASN unavailable')} · ${esc(geo.country||'Country unavailable')} · ${age(x.last_seen)}</small></button>`}catch(e){if(e.name!=='AbortError')box.innerHTML='<div class="search-loading">IP lookup unavailable. Press Enter to retry in IP Detail.</div>'}},400)}
function themeInit(){const theme=localStorage.getItem('cfc-theme')||'dark';document.documentElement.dataset.theme=theme;$('themeBtn').textContent=theme==='dark'?'☀':'☾'}
function themeToggle(){localStorage.setItem('cfc-theme',document.documentElement.dataset.theme==='dark'?'light':'dark');themeInit()}
function showLogin(){me=null;routeController?.abort();clearInterval(pulseTimer);pulseTimer=null;clearInterval(liveTicker);liveTicker=null;clearInterval(policyTicker);policyTicker=null;$('login').classList.remove('hidden');$('app').classList.add('hidden')}
function showApp(){$('login').classList.add('hidden');$('app').classList.remove('hidden');$('userLabel').textContent=`${me.username} · ${me.role}`;document.querySelector('.user-avatar').textContent=me.username.slice(0,1).toUpperCase();themeInit();if(!pulseTimer){refreshPulse();pulseTimer=setInterval(refreshPulse,15000)}}
async function checkLoginOptions(){try{const [o,l]=await Promise.all([api('/api/v1/auth/oidc/status',{signal:null}),api('/api/v1/auth/ldap/status',{signal:null})]);$('ssoBtn').classList.toggle('hidden',!o.enabled);$('ldapBtn').classList.toggle('hidden',!l.enabled)}catch{}}
async function boot(){themeInit();try{const x=await api('/api/v1/auth/me',{signal:null});me=x.user||x;csrf=x.csrf||'';showApp();await render()}catch{showLogin();checkLoginOptions()}}
$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginError').textContent='';const button=e.submitter;button.disabled=true;try{const x=await api('/api/v1/auth/login',{method:'POST',signal:null,body:JSON.stringify({username:$('username').value,password:$('password').value})});csrf=x.csrf||'';me=x.user;$('password').value='';showApp();await render()}catch(err){$('loginError').textContent=err.message}finally{button.disabled=false}};
$('ssoBtn').onclick=()=>location.assign('/api/v1/auth/oidc/start');
$('ldapBtn').onclick=async()=>{try{const x=await api('/api/v1/auth/ldap/login',{method:'POST',signal:null,body:JSON.stringify({username:$('username').value,password:$('password').value})});csrf=x.csrf||'';me=x.user;$('password').value='';showApp();render()}catch(e){$('loginError').textContent=e.message}};
$('passkeyBtn').classList.add('hidden');
$('logoutBtn').onclick=async()=>{try{await api('/api/v1/auth/logout',{method:'POST',body:'{}'});resourceCache.clear();showLogin()}catch(e){toast(e.message,'bad')}};
$('refreshBtn').onclick=()=>{resourceCache.clear();render();refreshPulse()};$('themeBtn').onclick=themeToggle;
$('fullscreenBtn').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Full screen is unavailable in this browser.','bad')}};
$('sidebarToggle').onclick=()=>{const collapsed=$('app').classList.toggle('sidebar-collapsed');$('sidebarToggle').setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar')};
$('mobileMenu').onclick=()=>{$('app').classList.toggle('mobile-nav-open')};
$('globalSearch').oninput=e=>scheduleSearch(e.target.value);$('globalSearch').onkeydown=e=>{if(e.key==='Enter')globalSearch(e.target.value);if(e.key==='Escape')hideSearch();if(e.key==='ArrowDown'){$('searchResults').querySelector('button')?.focus();e.preventDefault()}};
$('modal').onclick=e=>{if(e.target===$('modal'))closeModal()};
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(e.target.closest('[data-modal-close]')){closeModal();return}if(!b)return;
  if(b.dataset.page||b.dataset.route)return goto(b.dataset.page||b.dataset.route);
  if(b.hasAttribute('data-retry'))return render();
  if(b.hasAttribute('data-about'))return showAbout();
  if(b.dataset.ip)return ipDetail(b.dataset.ip);
  if(b.hasAttribute('data-copy'))return copyValue(b.dataset.copy);
  if(b.hasAttribute('data-add-filter'))return filterEditor();
  if(b.dataset.editFilter)return filterEditor(b.dataset.editFilter);
  if(b.dataset.removeFilter||b.hasAttribute('data-clear-filters')){const f=b.hasAttribute('data-clear-filters')?{}:urlFlowFilters();delete f[b.dataset.removeFilter];setURL(timeURL(PortalState.setFilters(location.href,f)));return render()}
  if(b.dataset.source&&b.dataset.destination){const u=PortalState.setFilters(location.href,{...urlFlowFilters(),src_cidr:b.dataset.source,dst_cidr:b.dataset.destination});u.searchParams.set('page','flows');setURL(timeURL(u));return render()}
  if(b.dataset.filterPort&&Number(b.dataset.value)>0)return drill(b.dataset.filterPort,b.dataset.value);
  if(b.classList.contains('drill'))return drill(b.dataset.dim,b.dataset.key);
  if(b.hasAttribute('data-row'))return rowDetail(Number(b.dataset.row));
  if(b.dataset.traffic){const u=new URL(location.href);u.searchParams.set('page','traffic');u.searchParams.set('dimension',b.dataset.traffic);setURL(timeURL(u));return render()}
});
document.addEventListener('keydown',e=>{
  if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)){e.preventDefault();$('globalSearch').focus()}
  if(e.key==='Escape'){closeModal();hideSearch();$('app').classList.remove('mobile-nav-open')}
  if(e.key==='Tab'&&!$('modal').classList.contains('hidden')){const focusable=$$('#modal button:not([disabled]),#modal a[href],#modal input:not([disabled]),#modal select:not([disabled]),#modal textarea:not([disabled])').filter(el=>el.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
});
window.onpopstate=()=>{hideSearch();render()};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&me){refreshPulse();if(rangeKey==='live')render()}});
// All lexical state is initialized before authentication can render a route.
boot();
